#include <libproc.h>
#include <sys/proc_info.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char **argv){if(argc!=2)return 2; struct proc_bsdinfo info; if(proc_pidinfo(atoi(argv[1]),PROC_PIDTBSDINFO,0,&info,sizeof(info))!=sizeof(info))return 3; printf("%llu\n",(unsigned long long)info.pbi_start_tvsec*1000000ULL+info.pbi_start_tvusec); return 0;}
